import{_ as s,o as t,c as a,a3 as i}from"./chunks/framework.Ch_0qWu9.js";const k=JSON.parse('{"title":"Score calculation","description":"","frontmatter":{"sourcePath":"docs/scoring.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/29e5ae6c70cf7268cd38de5cf59f4e08507b1ff6/docs/scoring.md","alternateUrl":"/TCSExam/docs/zh/scoring/","alternateAnchors":{"score-calculation":"score-calculation","the-four-track-scores":"the-four-track-scores","average-in-this-order":"average-in-this-order","fixed-reference-solver-calculation":"fixed-reference-solver-calculation","from-instance-records-to-a-task-score":"from-instance-records-to-a-task-score","attempt-table":"attempt-table","recalculate-an-index":"recalculate-an-index"}},"headers":[],"relativePath":"scoring/index.md","filePath":"scoring/index.md"}'),n={name:"scoring/index.md"};function o(r,e,l,d,c,h){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="score-calculation" tabindex="-1">Score calculation <a class="header-anchor" href="#score-calculation" aria-label="Permalink to &quot;Score calculation&quot;">​</a></h1><p>Score formulas, input formats and aggregation for TCSExam. For researchers computing task scores and the combined Index.</p><p>TCSExam reports four track scores and their weighted Index. The task checker&#39;s original reward is retained in the evaluation output. The Index uses complete proof indicators for the two proof tracks, fixed-reference relative scores for Solver, and original rewards for constructions.</p><h2 id="the-four-track-scores" tabindex="-1">The four track scores <a class="header-anchor" href="#the-four-track-scores" aria-label="Permalink to &quot;The four track scores&quot;">​</a></h2><p>Read each row for the value to put in the attempt table.</p><table tabindex="0"><thead><tr><th>Track</th><th>Value used by the Index</th><th>Range</th></tr></thead><tbody><tr><td>Theorem proving</td><td>Complete proof accepted by the checker: 1; otherwise 0</td><td>0–1</td></tr><tr><td>Solver engineering</td><td>Instance outcomes compared with the fixed references supplied in the <a href="https://github.com/MoonshotAI/TCSExam/blob/29e5ae6c70cf7268cd38de5cf59f4e08507b1ff6/src/tcsexam/references/paper-k3-fixed-260925-full.json" target="_blank" rel="noreferrer">Full</a> and <a href="https://github.com/MoonshotAI/TCSExam/blob/29e5ae6c70cf7268cd38de5cf59f4e08507b1ff6/src/tcsexam/references/paper-k3-fixed-260925-lite.json" target="_blank" rel="noreferrer">Lite</a> JSON files</td><td>0–1</td></tr><tr><td>Constructions</td><td>Original task reward, including above-reference credit</td><td>Nonnegative; may exceed 1</td></tr><tr><td>Open conjectures</td><td>Complete proof or refutation accepted: 1; otherwise 0</td><td>0–1</td></tr></tbody></table><p>The fixed reference contains the frozen K3 instance outcomes used to define Solver&#39;s relative score. Its version and values stay fixed when evaluating additional models. Full uses reference ID <code>paper-k3-fixed-260925-public-disjoint-261105</code>; Lite uses <code>paper-k3-fixed-260925</code>. The five Lite tasks have exactly the same reference values in both files.</p><p>Full uses <a href="https://github.com/MoonshotAI/TCSExam/blob/29e5ae6c70cf7268cd38de5cf59f4e08507b1ff6/assets/data/solver/final-evaluation-selection.json" target="_blank" rel="noreferrer">final selection <code>public-disjoint-final-261105</code></a>. MaxSAT has 200 final instances, of which 177 enter the relative score; Radiation has 36 final instances, all of which enter the relative score. These final sets exclude instances shared with their public development sets. The retained instance names, reference values and scoring formula stay fixed. Keep the selection ID and the <code>reference_id</code> returned by <code>solver-score</code> with reported results. Historical platform rewards remain associated with their original instance sets; recomputed results identify the selected set.</p><p>The original checker output can contain partial theorem credit or intermediate open-conjecture results. Convert these to 0 unless the checker accepted a complete proof or resolution. Construction formulas remain unchanged.</p><p>The Index is <code>30P + 30S + 30C + 10O</code>, where the letters are the theorem, Solver, construction and open-conjecture track means. Its metric identifier is <code>tcsexam-index-original-30303010-v0.1</code>. Report Index points together with all four track means. Because construction rewards can exceed 1, the Index can exceed 100.</p><h2 id="average-in-this-order" tabindex="-1">Average in this order <a class="header-anchor" href="#average-in-this-order" aria-label="Permalink to &quot;Average in this order&quot;">​</a></h2><ol><li>Average the adopted repetitions of each task.</li><li>Average task means equally within each track.</li><li>Multiply track means by 30, 30, 30 and 10 and add them.</li></ol><p>A task repeated three times receives the same track weight as a task repeated once. Missing tasks or planned repetitions produce an incomplete result with a null Index. Track weights stay fixed. An otherwise complete result containing provisional attempts is labelled provisional. Report Full and Lite separately, and separate online and offline Solver protocols within each suite.</p><h2 id="fixed-reference-solver-calculation" tabindex="-1">Fixed-reference Solver calculation <a class="header-anchor" href="#fixed-reference-solver-calculation" aria-label="Permalink to &quot;Fixed-reference Solver calculation&quot;">​</a></h2><p>For each reference instance, let <code>mu</code> be the mean of its fixed reference values and <code>s</code> their sample standard deviation. Set <code>scale = max(s, 0.02 * abs(mu), 1e-9)</code>. For a valid candidate value <code>A</code>:</p><ul><li>maximization: <code>z = (A - mu) / scale</code>;</li><li>minimization: <code>z = (mu - A) / scale</code>;</li><li>instance score: <code>Phi(z)</code>, the standard normal cumulative distribution function.</li></ul><p>Average the eligible instance scores to obtain the task score. A valid value equal to <code>mu</code> receives 0.5. A solver-level invalid submission, timeout or crash receives 0 for that instance. Missing results and infrastructure failures require repairing the judging input before scoring; they are incomplete observations.</p><p>The Full reference includes 1,838 eligible instances; 32 additional instances had fewer than two usable reference outcomes and are listed in <code>unscored_reference_instances</code>. Keep their observed outcomes in the result records. The scorer reports records outside the eligible set as <code>unscored_instances</code> and leaves them out of the mean. This fixed-reference metric is separate from baseline and known-best-value denominators in original checker rewards.</p><p>Each reference task declares <code>kind: &quot;objective&quot;</code> for objective values or <code>kind: &quot;solve&quot;</code> for solved indicators, plus its direction and reference values. For <code>solve</code>, the same formula uses 1 for solved and 0 for unsolved. Every reference instance needs at least two usable values. Custom references must supply these fields and both scale floors; version a changed reference separately.</p><h2 id="from-instance-records-to-a-task-score" tabindex="-1">From instance records to a task score <a class="header-anchor" href="#from-instance-records-to-a-task-score" aria-label="Permalink to &quot;From instance records to a task score&quot;">​</a></h2><p>Save the final judge&#39;s instance outcomes as a JSON list. Objective records use <code>instance</code>, <code>status</code> and <code>A</code>; solve-rate records can use a Boolean <code>solved</code> instead of <code>A</code>. Use <code>status: &quot;ok&quot;</code> only for a valid evaluated outcome. A completed solver failure uses the corresponding failure status, such as <code>timeout</code>, <code>invalid</code> or <code>certificate_failed</code>.</p><p>For example, a two-instance maximization calculation could have these records:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;instance&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;example-1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;A&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;instance&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;example-2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;timeout&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>If the first instance&#39;s reference values are <code>[10, 12, 14]</code>, its <code>mu</code> is 12, <code>scale</code> is 2 and score is 0.5. The timeout scores 0, giving a task mean of 0.25. These names and numbers illustrate the formula. For an evaluation, use the actual task&#39;s complete final records and the selected fixed reference:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> solver-score</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> maxcut-mqlib</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --records</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-final-instance-records.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reference</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lite</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/maxcut-relative.json</span></span></code></pre></div><p>The output contains <code>relative_score</code>, per-instance scores, unscored instance names and <code>reference_id</code>. Put <code>relative_score</code> into the attempt table; retain the raw checker reward and records alongside it. A missing eligible instance, duplicate name or infrastructure status causes an error.</p><h2 id="attempt-table" tabindex="-1">Attempt table <a class="header-anchor" href="#attempt-table" aria-label="Permalink to &quot;Attempt table&quot;">​</a></h2><p>Use one CSV row per attempt with these columns:</p><div class="language-csv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">track,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">item,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">attempt,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">score,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">adoption_status,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">score_status,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">score_type,</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">solver_protocol</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">my-model,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">solver,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">maxcut-mqlib,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">1,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">0.25,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">selected,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">valid,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fixed_reference_relative,</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">offline</span></span></code></pre></div><p>The score above illustrates the row format. Populate it with the actual <code>relative_score</code> produced for that task and attempt. Add the remaining selected tasks and planned repetitions before computing an Index.</p><p>Read the table by field. A legitimate zero is a valid observed score.</p><table tabindex="0"><thead><tr><th>Field</th><th>Values and meaning</th></tr></thead><tbody><tr><td><code>adoption_status</code></td><td><code>selected</code> adopts an attempt; <code>selected_provisional</code> adopts it provisionally; <code>excluded</code> retains an attempt outside the aggregate.</td></tr><tr><td><code>score_status</code></td><td><code>valid</code> includes legitimate zeros. States such as <code>judge_failed</code>, <code>not_finished</code> and <code>missing</code> leave the planned result incomplete.</td></tr><tr><td><code>score_type</code></td><td>Solver requires <code>fixed_reference_relative</code>. Other tracks can use <code>original_task_score</code>, with theorem and open-conjecture scores already converted to 0 or 1.</td></tr><tr><td><code>solver_protocol</code></td><td>Solver rows declare <code>online</code> or <code>offline</code>; other tracks may leave this empty.</td></tr><tr><td><code>attempt</code></td><td>An identifier unique within each model, track and task.</td></tr></tbody></table><p>Declare the planned repetitions and adoption policy before aggregation. If an attempt is replaced, retain its row as <code>excluded</code> and record why the replacement was adopted. The aggregator rejects duplicate identities and excess adopted repetitions.</p><h2 id="recalculate-an-index" tabindex="-1">Recalculate an Index <a class="header-anchor" href="#recalculate-an-index" aria-label="Permalink to &quot;Recalculate an Index&quot;">​</a></h2><p>Create <code>cohort.json</code> to declare the suite, Solver protocol, fixed reference and number of adopted repetitions planned for every task:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;suite&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;lite&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;solver_protocol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;offline&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;solver_reference_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;paper-k3-fixed-260925&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;models&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;my-model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;attempts_per_task&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Prepare <code>attempts.csv</code> with all twenty Lite tasks, then run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> score</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lite</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --attempts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attempts.csv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cohort</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cohort.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/index.json</span></span></code></pre></div><p>All selected Solver rows must match the cohort protocol and use the declared reference. Preserve the <code>solver-score</code> outputs to show which reference produced them. Aggregation consumes the task scores and labels in the attempt table; retain the instance records alongside those scores.</p><p>For example, if the resulting track means are <code>P=0.4</code>, <code>S=0.25</code>, <code>C=1.2</code> and <code>O=0</code>, the Index is <code>30×0.4 + 30×0.25 + 30×1.2 + 10×0 = 55.5</code> points. If one planned task result is missing, the output instead has <code>status: &quot;incomplete&quot;</code> and <code>index: null</code>, with coverage and issues identifying the missing result.</p>`,40)])])}const u=s(n,[["render",o]]);export{k as __pageData,u as default};
